// Plays the pronunciations generated by scripts/tts.py.
// A button disables itself when its file is missing, for example in a local preview before running tts.py.

import { el } from './data.js';

const SPEAKER_ICON =
  '<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true" fill="none" stroke="currentColor" ' +
  'stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M11 5 6 9H2v6h4l5 4V5z"/>' +
  '<path d="M15.5 8.5a5 5 0 0 1 0 7"/><path d="M19 5a10 10 0 0 1 0 14"/></svg>';

let current = null;

// Plays a word's audio. The optional button shows the playing state and is disabled if the file fails to load.
export function playWord(word, button) {
  if (!word.audio || button?.disabled) return;
  current?.audio.pause();
  current?.button?.classList.remove('playing');

  const audio = new Audio(word.audio);
  current = { audio, button };
  button?.classList.add('playing');
  audio.addEventListener('ended', () => button?.classList.remove('playing'));
  audio.addEventListener('error', () => {
    if (!button) return;
    button.classList.remove('playing');
    button.disabled = true;
    button.title = 'No audio for this word yet';
  });
  // play() rejects when the browser blocks autoplay; the button still works on the next click.
  audio.play().catch(() => button?.classList.remove('playing'));
}

export function speakButton(word) {
  if (!word.audio) return null;
  const button = el('button', {
    type: 'button',
    class: 'speak',
    title: 'Listen',
    'aria-label': `Listen: ${word.kk}`,
    onclick: (event) => {
      event.stopPropagation();
      playWord(word, button);
    },
  });
  button.innerHTML = SPEAKER_ICON;
  return button;
}
